} | {
    kind: 'scene.object';
    command: SceneObjectCommand;
} | {
    kind: 'adventure';
    command: import('@aelzerant/contracts').AdventureCommand;
} | DndCreationAction | {
    kind: 'lancer.deployment';
    command: DeploymentCommand;
} | {
    kind: 'combat.rollback';
