} | {
    kind: 'story.use';
    request: ResourceUse;
} | TableStoryAction | {
    kind: 'dnd';
    intent: DndIntent;
} | {
    kind: 'maintenance';
    intent: LancerMaintenanceIntent;
} | {
    kind: 'appearance';
    id: string;
    model?: string;
    image?: string;
    color?: string;
} | {
    kind: 'move';
    id: string;
    x: number;
    y: number;
    z: number;
    mode?: MovementChoice;
    path?: MovementPoint[];
} | {
    kind: 'chat';
    text: string;
} | {
    kind: 'roll';
    expression: string;
} | {
    kind: 'actor';
