export interface KVStorage {
    get(key: string): string | null;
    set(key: string, value: string): void;
    remove(key: string): void;
}

export class MemoryStorage {
  get(k: string): string | null;
  set(k: string, v: string): void;
  remove(k: string): void;
}

interface CachedIndex {
    version: number;
    files: AssetFileMeta[];
}

export class AssetCache {
  constructor(storage: KVStorage);
  loadIndex(worldId: string): CachedIndex | null;
  read(worldId: string, path: string): unknown | null;
  readVersion(worldId: string, meta: AssetFileMeta): unknown | null;
  storeFile(worldId: string, meta: AssetFileMeta, data: unknown): Promise<void>;
  storeIndex(worldId: string, index: CachedIndex): void;
  deleteWorld(worldId: string): void;
  deleteFile(worldId: string, path: string): void;
  deleteVersion(worldId: string, meta: AssetFileMeta): void;
  sizeInWorld(worldId: string): number;
}

export interface SyncDeps {
    getManifest(): Promise<AssetManifest>;
    getFile(path: string): Promise<AssetPayload>;
}

export class WorldGoneError {
  constructor();
}

export interface SyncResult {
    worldId: string;
    version: number;
    pulled: string[];
    reused: number;
}

export interface MediaStorage {
    manifest(worldId: string): Promise<MediaManifest | null>;
    blob(worldId: string, hash: string): Promise<Blob | null>;
    commit(worldId: string, manifest: MediaManifest, blobs: Map<string, Blob>): Promise<void>;
    removeWorld(worldId: string): Promise<void>;
}

export class MediaCache {
  constructor(storage: MediaStorage);
  manifest(worldId: string): Promise<MediaManifest | null>;
  read(worldId: string, path: string): Promise<Blob | null>;
  sync(worldId: string, fetchManifest: () => Promise<MediaManifest>, fetchBlob: (file: MediaFile) => Promise<Blob>): Promise<{ version: number; pulled: number; reused: number; }>;
  removeWorld(worldId: string): Promise<void>;
}

export class IndexedDBMediaStorage {
  constructor(name?: string);
  manifest(worldId: string): Promise<MediaManifest | null>;
  blob(worldId: string, hash: string): Promise<Blob | null>;
  commit(worldId: string, manifest: MediaManifest, blobs: Map<string, Blob>): Promise<void>;
  removeWorld(worldId: string): Promise<void>;
}

